parameters.jsCode:
const webhookUrl = 'http://localhost:5678/webhook/complete-intake';

if (!$parameter.parent_name || !$parameter.parent_email || !$parameter.child_name) {
  return { success: false, message: "Missing required information." };
}

let availArray = $parameter.availability;
if (!Array.isArray(availArray)) {
  availArray = typeof availArray === 'string' ? 
    (availArray.includes(',') ? availArray.split(',').map(s => s.trim()) : [availArray]) : [];
}

const childAge = typeof $parameter.child_age === 'string' ? parseInt($parameter.child_age) : $parameter.child_age;
const examBool = typeof $parameter.exam === 'string' ? 
  ($parameter.exam.toLowerCase() === 'yes' || $parameter.exam.toLowerCase() === 'true') : Boolean($parameter.exam);

const data = {
  parent_name: String($parameter.parent_name),
  parent_email: String($parameter.parent_email),
  parent_phone: String($parameter.parent_phone || 'Not provided'),
  child_name: String($parameter.child_name),
  child_age: childAge,
  year: String($parameter.year),
  subject: String($parameter.subject),
  exam: examBool,
  exam_date: String($parameter.exam_date || 'N/A'),
  availability: availArray,
  preference: String($parameter.preference),
  challenges: String($parameter.challenges),
  goals: String($parameter.goals),
  session_id: String($parameter.session_id || $executionId || Date.now())
};

console.log('📤', JSON.stringify(data, null, 2));

try {
  const res = await fetch(webhookUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data)
  });

  if (!res.ok) throw new Error(`${res.status}`);

  const result = res.headers.get('content-type')?.includes('json') ? await res.json() : await res.text();
  console.log('✅', result);

  return { success: true, message: `Perfect! Finding options for ${data.child_name}...`, submission_id: data.session_id };
} catch (err) {
  console.error('❌', err.message);
  return { success: false, message: "Connection issue. Please try again.", error: err.message };
}

